def solve_costas(n):
    import itertools
    for p in itertools.permutations(range(n)):
        valid = True
        for d in range(1, n):
            diffs = set()
            for i in range(n - d):
                diff = p[i+d] - p[i]
                if diff in diffs:
                    valid = False
                    break
                diffs.add(diff)
            if not valid:
                break
        if valid:
            return list(p)
    return None

print(solve_costas(9))
